"""Blind audit set for the no-file rules: 232 hand-written variants of the dev templates (sibling sub-templates),
written without reading the rule code. Ground truth comes from the Python expressions below, not from the agent."""
import math, statistics as st, datetime as dt, itertools as it
from math import comb, perm, gcd, factorial, log, log10, log2, exp, sqrt

T = []
def add(obj, val, nd=None, cat=""):
    T.append(dict(objective=obj, answer=float(val), nd=nd, cat=cat))
D = lambda y, m, d: dt.date(y, m, d)
def ymd(d): return d.year * 10000 + d.month * 100 + d.day
