add("A machine produces a defective part with probability 0.65. Among 9 parts, what is the probability of more than 7 defective ones? Report it with 4 decimals.", binom(9,.65,[8,9]), 4, "proba")
add("A machine produces a defective part with probability 0.65. Among 9 parts, what is the probability of fewer than 7 defective ones? Report it with 4 decimals.", binom(9,.65,range(0,7)), 4, "proba")
add("A machine produces a defective part with probability 0.65. Among 9 parts, what is the probability of at least 7 non-defective ones? Report it with 4 decimals.", binom(9,.35,[7,8,9]), 4, "proba")
add("A machine produces a defective part with probability 0.65. Among 9 parts, what is the probability of no defective one? Report it with 6 decimals.", .35**9, 6, "proba")
add("A machine produces a defective part with probability 0.65. Among 9 parts, what is the expected number of defective ones? Report it with 2 decimals.", 5.85, 2, "proba")
add("A machine produces a defective part with probability 0.05. Among 9 parts, what is the probability of at least one defective part? Report it with 4 decimals.", 1-.95**9, 4, "proba")
dice = lambda n, pred: sum(pred(r) for r in it.product(range(1,7), repeat=n))/6**n
add("3 fair six-sided dice are thrown. What is the probability that the faces add up to at least 14? Round your answer to 4 decimal places.", dice(3, lambda r: sum(r)>=14), 4, "proba")
add("3 fair six-sided dice are thrown. What is the probability that the faces add up to at most 5? Round your answer to 4 decimal places.", dice(3, lambda r: sum(r)<=5), 4, "proba")
add("2 fair six-sided dice are thrown. What is the probability that the faces add up to 7? Round your answer to 4 decimal places.", dice(2, lambda r: sum(r)==7), 4, "proba")
add("3 fair six-sided dice are thrown. What is the probability that all three faces are equal? Round your answer to 4 decimal places.", dice(3, lambda r: len(set(r))==1), 4, "proba")
add("3 fair six-sided dice are thrown. What is the probability that at least one face shows a 6? Round your answer to 4 decimal places.", dice(3, lambda r: 6 in r), 4, "proba")
add("3 fair six-sided dice are thrown. What is the probability that the product of the faces is 12? Round your answer to 4 decimal places.", dice(3, lambda r: r[0]*r[1]*r[2]==12), 4, "proba")
add("3 fair six-sided dice are thrown. What is the probability that the largest face is 4? Round your answer to 4 decimal places.", dice(3, lambda r: max(r)==4), 4, "proba")
add("3 fair four-sided dice (faces 1 to 4) are thrown. What is the probability that the faces add up to 9? Round your answer to 4 decimal places.", sum(sum(r)==9 for r in it.product(range(1,5), repeat=3))/64, 4, "proba")
add("A bag holds 5 red balls and 7 blue balls. Two balls are drawn without replacement. What is the probability that both are red? Round to 4 decimals.", 5/12*4/11, 4, "proba")
add("A bag holds 5 red balls and 7 blue balls. Two balls are drawn with replacement. What is the probability that both are red? Round to 4 decimals.", (5/12)**2, 4, "proba")
add("A fair coin is tossed 10 times. What is the probability of exactly 6 heads? Round to 4 decimals.", comb(10,6)/1024, 4, "proba")

# ---------------- statistiques en ligne
A = [64.62, 95.29, 30.42, 28.19, 67.74, 64.1, 85.05, 93.81, 21.34, 26.32, 83.87]
P = [10.5, 27.8, 21.4, 11.9, 26.8, 30.7, 22.4, 26.2, 42.5]
Q = [6.8, 13.3, 26.6, 3.3]
E8 = [10.5, 27.8, 21.4, 11.9, 26.8, 30.7, 22.4, 26.2]
add(f"The delivery delays of 11 orders were {s(A)} (hours). The measurements were checked twice. What is the median? Round to 2 decimals.", st.median(A), 2, "stats")
add(f"The delivery delays of 11 orders were {s(A)} (hours). What is the range (largest minus smallest)? Round to 2 decimals.", max(A)-min(A), 2, "stats")
add(f"The delivery delays of 11 orders were {s(A)} (hours). What is their sample standard deviation (divide by n − 1)? Round to 2 decimals.", st.stdev(A), 2, "stats")
add(f"The delivery delays of 11 orders were {s(A)} (hours). What is their population variance (divide by n)? Round to 2 decimals.", st.pvariance(A), 2, "stats")
add(f"The delivery delays of 11 orders were {s(A)} (hours). What is their sample variance (divide by n − 1)? Round to 2 decimals.", st.variance(A), 2, "stats")
add(f"The delivery delays of 11 orders were {s(A)} (hours). What is the mean, in minutes? Round to 2 decimals.", st.mean(A)*60, 2, "stats")
add(f"The delivery delays of 11 orders were {s(A)} (hours). What is the mean of the three longest delays? Round to 2 decimals.", st.mean(sorted(A)[-3:]), 2, "stats")
add(f"The delivery delays of 11 orders were {s(A)} (hours). What is the mean once the largest and the smallest values are removed? Round to 2 decimals.", st.mean(sorted(A)[1:-1]), 2, "stats")
add(f"The delivery delays of 11 orders were {s(A)} (hours). How many delays are above the mean? Give a whole number.", sum(x > st.mean(A) for x in A), 0, "stats")
add(f"The delivery delays of 11 orders were {s(A)} (hours). What is the sum? Round to 2 decimals.", sum(A), 2, "stats")
add(f"The delivery delays of 11 orders were {s(A)} (hours). A twelfth order took 50 hours. What is the mean of the 12 delays? Round to 2 decimals.", (sum(A)+50)/12, 2, "stats")
add(f"The weights of 9 parcels leaving a warehouse were {s(P)} (kg). Values are listed in the order they were recorded. What is the mean? Give the answer rounded to 2 decimal places.", st.mean(P), 2, "stats")
add(f"The weights of 8 parcels leaving a warehouse were {s(E8)} (kg). Values are listed in the order they were recorded. What is the median? Give the answer rounded to 2 decimal places.", st.median(E8), 2, "stats")
add(f"The weights of 9 parcels leaving a warehouse were {s(P)} (kg). What is the heaviest parcel? Give the answer rounded to 2 decimal places.", max(P), 2, "stats")
add(f"The weights of 9 parcels leaving a warehouse were {s(P)} (kg). What is the total weight, in grams? Give a whole number.", sum(P)*1000, 0, "stats")
add(f"The weights of 9 parcels leaving a warehouse were {s(P)} (kg). What is the median of the first five values? Give the answer rounded to 2 decimal places.", st.median(P[:5]), 2, "stats")
add(f"The weights of 9 parcels leaving a warehouse were {s(P)} (kg). What is the third largest value? Give the answer rounded to 2 decimal places.", sorted(P)[-3], 2, "stats")
add(f"A runner logged these lap times over 4 laps: {s(Q)} (seconds). What is their sample standard deviation (divide by n − 1)? Report it with 2 decimals.", st.stdev(Q), 2, "stats")
add(f"A runner logged these lap times over 4 laps: {s(Q)} (seconds). What is their standard deviation (divide by n)? Report it with 2 decimals.", st.pstdev(Q), 2, "stats")
add(f"A runner logged these lap times over 4 laps: {s(Q)} (seconds). What is the total time? Report it with 2 decimals.", sum(Q), 2, "stats")
add(f"A runner logged these lap times over 4 laps: {s(Q)} (seconds). What is the average speed in metres per second if each lap is 100 metres long? Report it with 2 decimals.", 400/sum(Q), 2, "stats")
add(f"A runner logged these lap times over 4 laps: {s(Q)} (seconds). What is the coefficient of variation (population standard deviation divided by the mean)? Report it with 3 decimals.", st.pstdev(Q)/st.mean(Q), 3, "stats")
wm = lambda pairs: sum(a*b for a,b in pairs)/sum(b for a,b in pairs)
add("A student has 18.6 in history (coefficient 2), 12.6 in economics (coefficient 1), 5.2 in biology (coefficient 5) and 10.5 in English (coefficient 1). What is the unweighted mean of the marks? Report it with 2 decimals.", st.mean([18.6,12.6,5.2,10.5]), 2, "stats")
add("A student has 18.6 in history (coefficient 2), 12.6 in economics (coefficient 1), 5.2 in biology (coefficient 5) and 10.5 in English (coefficient 1). What is the sum of the coefficients? Give a whole number.", 9, 0, "stats")
add("A student has 18.6 in history (coefficient 2), 12.6 in economics (coefficient 1) and 5.2 in biology (coefficient 5). What mark in English (coefficient 1) gives a weighted mean of exactly 10? Report it with 2 decimals.", 10*9-(18.6*2+12.6+5.2*5), 2, "stats")
add("A student has 18.6 in history (coefficient 2), 12.6 in economics (coefficient 1), 5.2 in biology (coefficient 5) and 10.5 in English (coefficient 1). What is the weighted mean of the marks without biology? Report it with 2 decimals.", wm([(18.6,2),(12.6,1),(10.5,1)]), 2, "stats")
add("A student has 17 in chemistry (weight 50%), 14 in physics (weight 10%) and 10 in biology (weight 40%). What is the weighted mean of the marks? Round your answer to 2 decimal places.", 17*.5+14*.1+10*.4, 2, "stats")
add("A student has 17 in chemistry (coefficient 5), 14 in physics (coefficient 1) and 10 in biology (coefficient 5). What is the highest mark? Round your answer to 2 decimal places.", 17, 2, "stats")

